<?php require 'config/db.php';require 'includes/functions.php';$filter=$_GET['priority']??'all';$where="br.status NOT IN ('completed','cancelled')";if(in_array($filter,['critical','urgent','normal']))$where.=" AND br.priority='".$conn->real_escape_string($filter)."'";$rs=$conn->query("SELECT br.*,h.name hospital_name,(SELECT COUNT(*) FROM request_matches rm WHERE rm.request_id=br.id) matches FROM blood_requests br LEFT JOIN hospitals h ON h.id=br.hospital_id WHERE $where ORDER BY FIELD(br.priority,'critical','urgent','normal'),br.created_at DESC");$pageTitle='Active Requests';include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="kicker">Live request board</span><h1>Active blood requests</h1><p>Browse current cases without exposing donor contact information.</p></div></section><section class="section-sm"><div class="container"><div class="filters"><?php foreach(['all'=>'All','critical'=>'Critical','urgent'=>'Urgent','normal'=>'Normal'] as $k=>$v):?><a class="<?=$filter===$k?'active':''?>" href="?priority=<?=$k?>"><?=$v?></a><?php endforeach;?></div><div class="requests-grid"><?php while($r=$rs->fetch_assoc()):?><article class="request-card"><div class="request-top"><div class="blood-ball"><?=e($r['blood_group'])?></div><span class="priority <?=e($r['priority'])?>"><?=priority_icon($r['priority'])?> <?=e($r['priority'])?></span></div><h3><?=e($r['patient_name'])?></h3><p><i class="fa-solid fa-hospital"></i> <?=e($r['hospital_name']?:$r['address'])?></p><div class="meta"><div><span>Units</span><b><?=$r['units']?></b></div><div><span>Matched</span><b><?=$r['matches']?> donor(s)</b></div></div><div class="card-actions"><span class="status"><?=e(status_label($r['status']))?></span><a class="btn btn-sm btn-ghost" href="request-view.php?id=<?=$r['id']?>">Live case</a></div></article><?php endwhile;?></div></div></section><?php include 'includes/footer.php';?>
